/** The structures the product offers (paper-brick and 17 more, three in each family). Keep equal to backend ENABLED_THEME_IDS (a test checks it). */
export const ENABLED_THEME_IDS: string[] = ["paper-brick", "canopy-grove", "softform", "japandi-atelier", "clay-pastel", "pearl", "product", "mela-noir", "lotus-hour", "kash-meadow", "denim-linen", "terracotta-hall", "hush-pond", "linen-arch", "ledger-gazette", "marquee-showbill", "product-console", "sage-round"]
export const THEMES: ThemeDef[] = ALL_THEMES.filter((t) => ENABLED_THEME_IDS.includes(t.id))
/** Built and kept in the code, still valid for a square already on one; not offered to anyone new and not shown in the pickers. */
export const LEGACY_THEMES: ThemeDef[] = ALL_THEMES.filter((t) => !ENABLED_THEME_IDS.includes(t.id))
/** Themes shown as coming up: none planned (the pickers hide the section when this is empty). */
export const COMING_THEMES: ThemeDef[] = []

export const DEFAULT_TENANT_THEME = 'paper-brick'

// Lookups by id cover every theme, so a square on a retired one still shows its name.
export const getTheme = (id: string): ThemeDef | undefined => ALL_THEMES.find((t) => t.id === id)
export const isThemeId = (id: unknown): id is string => typeof id === 'string' && ALL_THEMES.some((t) => t.id === id)
